<?= $this->extend('layouts/main') ?>
<?= $this->section('content') ?>
<section class="wrap products-section"><h1>Checkout</h1><?php if (session('error')): ?><p role="alert"><?= esc(session('error')) ?></p><?php endif ?>
<?php if (! $ready): ?><p class="empty">Checkout is not available yet. Payment instructions have not been configured.</p><?php elseif (! $items): ?><p>Your cart is empty. <a href="<?= site_url('catalog') ?>">Explore products</a></p><?php else: ?>
<?php if ($tooLarge): ?><p role="alert">Order total is too large. Please update your cart.</p><a href="<?= site_url('cart') ?>">Return to cart</a><?php else: ?><h2>Order items</h2><?php foreach ($items as $item): ?><p><?= esc($item['name']) ?> × <?= esc($item['quantity']) ?> — <?= format_rupiah((string) $item['price']) ?> each</p><?php endforeach ?>
<p>Subtotal: <?= format_rupiah(cents_to_money($subtotal)) ?></p><p>Shipping: <?= format_rupiah((string) $settings['shipping_cost']) ?></p><p><strong>Total: <?= format_rupiah(cents_to_money($total)) ?></strong></p><?php if (! $itemsAvailable): ?><p role="alert">Some items are no longer available in the requested quantity. Please update your cart.</p><?php endif ?>
<?php if (! $itemsAvailable): ?><a href="<?= site_url('cart') ?>">Return to cart</a><?php elseif (! $addresses): ?><p>Add a delivery address before checking out.</p><a href="<?= site_url('account/addresses') ?>">Add an address</a><?php else: ?><form class="account-form" method="post" action="<?= site_url('checkout') ?>"><?= csrf_field() ?><input type="hidden" name="checkout_token" value="<?= esc($token) ?>"><label for="address_id">Delivery address</label><select id="address_id" name="address_id" required><?php foreach ($addresses as $address): ?><option value="<?= esc($address['id']) ?>"><?= esc($address['recipient_name'] . ' — ' . $address['address'] . ', ' . $address['city']) ?></option><?php endforeach ?></select><button type="submit" class="button button-dark">Place order</button></form><?php endif ?><?php endif ?><?php endif ?></section>
<?= $this->endSection() ?>
